L38_1 = "\236\149\132\234\176\128\237\133\140\235\157\188\234\179\160 \235\182\136\235\159\172\236\154\148. \236\167\145\236\149\136\236\151\144\236\132\156 \235\182\128\235\165\180\235\141\152 \236\157\180\235\166\132\236\157\180\235\157\188 \235\156\187\236\157\128 \236\158\152 \235\170\168\235\165\180\236\167\128\235\167\140\236\154\148."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "\227\130\162\227\130\172\227\131\188\227\131\134\227\129\168\232\168\128\227\129\132\227\129\190\227\129\153\227\128\130\n\230\152\148\227\129\139\227\130\137\229\174\182\227\129\174\228\186\186\227\129\171\227\129\157\227\129\134\229\145\188\227\129\176\227\130\140\227\129\166\227\129\132\227\129\159\227\129\174\227\129\167\227\128\129\230\132\143\229\145\179\227\129\175\227\130\136\227\129\143\227\130\143\227\129\139\227\130\138\227\129\190\227\129\155\227\130\147\227\128\130"
L37_1.m_Talk_JPN = L38_1
L38_1 = "She's called Agathe. My family named her, so I don't know what that means."
L37_1.m_Talk_ENG = L38_1
L38_1 = "\229\174\131\229\143\171\232\137\190\229\141\161\231\137\185\239\188\140\230\152\175\231\165\150\229\130\179\228\184\139\228\190\134\231\154\132\229\144\141\229\173\151\239\188\140\230\137\128\228\187\165\230\136\145\228\185\159\228\184\141\230\152\175\229\190\136\230\184\133\230\165\154\229\144\141\229\173\151\231\154\132\230\182\181\231\190\169\227\128\130"
L37_1.m_Talk_TWN = L38_1
L38_1 = "\224\184\138\224\184\183\224\185\136\224\184\173\224\184\173\224\184\176\224\184\129\224\184\178\224\185\128\224\184\151\224\184\132\224\185\136\224\184\176 \224\184\132\224\184\163\224\184\173\224\184\154\224\184\132\224\184\163\224\184\177\224\184\167\224\184\137\224\184\177\224\184\153\224\184\149\224\184\177\224\185\137\224\184\135\224\185\131\224\184\171\224\185\137 \224\184\137\224\184\177\224\184\153\224\185\128\224\184\165\224\184\162\224\185\132\224\184\161\224\185\136\224\184\163\224\184\185\224\185\137\224\184\167\224\185\136\224\184\178\224\184\171\224\184\161\224\184\178\224\184\162\224\184\150\224\184\182\224\184\135\224\184\173\224\184\176\224\185\132\224\184\163"
L37_1.m_Talk_THA = L38_1
L38_1 = "N\195\179 t\195\170n l\195\160 Agathe. Gia \196\145\195\172nh em \196\145\225\186\183t t\195\170n cho n\195\179, n\195\170n em kh\195\180ng bi\225\186\191t n\195\179 c\195\179 ngh\196\169a l\195\160 g\195\172."
L37_1.m_Talk_VTN = L38_1
L38_1 = "\229\143\171\233\152\191\229\138\160\231\137\185\227\128\130\229\164\167\229\174\182\233\131\189\230\152\175\232\191\153\228\185\136\229\143\171\231\154\132\229\145\162\239\188\140\230\137\128\228\187\165\230\136\145\228\185\159\228\184\141\231\159\165\233\129\147\229\133\183\228\189\147\231\154\132\230\132\143\230\128\157\227\128\130"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Sie hei\195\159t Agathe. Meine Familie hat sie benannt, also wei\195\159 ich nicht, was das bedeutet."
